3: export default function pLimit(concurrency) {
4: 	let rejectOnClear = false;
5: 
6: 	if (typeof concurrency === 'object') {
7: 		({concurrency, rejectOnClear = false} = concurrency);
8: 	}
9: 
10: 	validateConcurrency(concurrency);
11: 
12: 	if (typeof rejectOnClear !== 'boolean') {
13: 		throw new TypeError('Expected `rejectOnClear` to be a boolean');
14: 	}
15: 
16: 	const queue = new Queue();
17: 	let activeCount = 0;
18: 
19: 	const resumeNext = () => {
20: 		// Process the next queued function if we're under the concurrency limit
21: 		if (activeCount < concurrency && queue.size > 0) {
22: 			activeCount++;
23: 			queue.dequeue().run();
24: 		}
25: 	};
26: 
27: 	const next = () => {
28: 		activeCount--;
29: 		resumeNext();
30: 	};
31: 
32: 	const run = async (function_, resolve, arguments_) => {
33: 		// Execute the function and capture the result promise
34: 		const result = (async () => function_(...arguments_))();
35: 
36: 		// Resolve immediately with the promise (don't wait for completion)
37: 		resolve(result);
38: 
39: 		// Wait for the function to complete (success or failure)
40: 		// We catch errors here to prevent unhandled rejections,
41: 		// but the original promise rejection is preserved for the caller
42: 		try {
43: 			await result;
44: 		} catch {}
45: 
46: 		// Decrement active count and process next queued function
47: 		next();
48: 	};
49: 
50: 	const enqueue = (function_, resolve, reject, arguments_) => {
51: 		const queueItem = {reject};
52: 
53: 		// Queue the internal resolve function instead of the run function
54: 		// to preserve the asynchronous execution context.
55: 		new Promise(internalResolve => { // eslint-disable-line promise/param-names
56: 			queueItem.run = internalResolve;
57: 			queue.enqueue(queueItem);
58: 		}).then(run.bind(undefined, function_, resolve, arguments_)); // eslint-disable-line promise/prefer-await-to-then
59: 
60: 		// Start processing immediately if we haven't reached the concurrency limit
61: 		if (activeCount < concurrency) {
62: 			resumeNext();
63: 		}
64: 	};
65: 
66: 	const generator = (function_, ...arguments_) => new Promise((resolve, reject) => {
67: 		enqueue(function_, resolve, reject, arguments_);
68: 	});
69: 
70: 	Object.defineProperties(generator, {
71: 		activeCount: {
72: 			get: () => activeCount,
73: 		},
74: 		pendingCount: {
75: 			get: () => queue.size,
76: 		},
77: 		clearQueue: {
78: 			value() {
79: 				if (!rejectOnClear) {
80: 					queue.clear();
81: 					return;
82: 				}
83: 
84: 				const abortError = AbortSignal.abort().reason;
85: 
86: 				while (queue.size > 0) {
87: 					queue.dequeue().reject(abortError);
88: 				}
89: 			},
90: 		},
91: 		concurrency: {
92: 			get: () => concurrency,
93: 
94: 			set(newConcurrency) {
95: 				validateConcurrency(newConcurrency);
96: 				concurrency = newConcurrency;
97: 
98: 				queueMicrotask(() => {
99: 					// eslint-disable-next-line no-unmodified-loop-condition
100: 					while (activeCount < concurrency && queue.size > 0) {
101: 						resumeNext();
102: 					}
103: 				});
104: 			},
105: 		},
106: 		map: {
107: 			async value(iterable, function_) {
108: 				const promises = Array.from(iterable, (value, index) => generator(function_, value, index));
109: 				return Promise.all(promises);
110: 			},
111: 		},
112: 	});
113: 
114: 	return generator;
115: }
