117: export function limitFunction(function_, options) {
118: 	const limit = pLimit(options);
119: 
120: 	const limitedFunction = (...arguments_) => limit(() => function_(...arguments_));
121: 	Object.defineProperty(limitedFunction, 'clearQueue', {
122: 		value: limit.clearQueue,
123: 	});
124: 
125: 	return limitedFunction;
126: }
